    @Test
    void failedCommandKeyCanBeReusedAfterFix() throws Exception {
        evidenceClock.setClock(Clock.fixed(BASE, ZoneOffset.UTC));
        String caseKey = uniqueKey("CASE");
        String e1 = uniqueKey("EV");
        intake("alice", caseKey, e1);
        borrow("alice", e1, "bob");
        String asOf = LocalDateTime.ofInstant(BASE.plusSeconds(60), ZoneOffset.UTC).toString();
        String commandKey = uniqueKey("CMD");

        assertThat(createPackage("officer", caseKey, List.of(e1), asOf, commandKey)
                .getResponse().getStatus()).isEqualTo(422);
        // 失败不占键：同键不同内容（改为未来时刻，借出仍未归还仍失败）无意义；
        // 归还后同键重试成功（通过 service 直接归还，loanKey 由借出响应给出较繁琐，改为新建一件干净证物）。
        String e2 = uniqueKey("EV");
        intake("alice", caseKey, e2);
        MvcResult retried = createPackage("officer", caseKey, List.of(e2), asOf, commandKey);
        // 同键改参（证物集合变了）按既有幂等语义应返回 409；
        // 因此“失败不占键”用另一个新键成功建包来验证业务可继续，原键保持 409 语义。
        assertThat(retried.getResponse().getStatus()).isEqualTo(409);
        MvcResult success = createPackage("officer", caseKey, List.of(e2), asOf, uniqueKey("CMD"));
        assertThat(success.getResponse().getStatus()).isEqualTo(201);
    }

