        intake("bob", uniqueKey("CASE-OTHER"), e3);
        String asOf = LocalDateTime.ofInstant(BASE.plusSeconds(60), ZoneOffset.UTC).toString();
        assertThat(createPackage("officer", caseKey, List.of(e1, e2), asOf, uniqueKey("CMD"))
                .getResponse().getStatus()).isEqualTo(201);

        // 最终集合含跨案件证物：422，已有版本 1 不变，不产生版本 2。
